#include <bits/stdc++.h>
using namespace std;

int main() {
    int V, N, M;
    if (scanf("%d %d %d", &V, &N, &M) != 3) return 0;

    vector<int> ea(M), eb(M), et(M), ep(M);
    for (int i = 0; i < M; i++) {
        scanf("%d %d %d %d", &ea[i], &eb[i], &et[i], &ep[i]);
        ea[i]--; eb[i]--;
    }
    int X, Y;
    scanf("%d %d", &X, &Y);
    X--; Y--;

    const int INF = INT_MAX;
    int C = V + 1;
    vector<vector<int>> dist(N, vector<int>(C, INF));

    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<tuple<int,int,int>>> pq;
    dist[X][0] = 0;
    pq.push({0, X, 0});

    while (!pq.empty()) {
        auto [d, u, c] = pq.top(); pq.pop();
        if (d > dist[u][c]) continue;
        for (int i = 0; i < M; i++) {
            int v, t, p;
            if (ea[i] == u) { v = eb[i]; t = et[i]; p = ep[i]; }
            else if (eb[i] == u) { v = ea[i]; t = et[i]; p = ep[i]; }
            else continue;
            int nc = c + p;
            if (nc > V) continue;
            int nd = d + t;
            if (nd < dist[v][nc]) {
                dist[v][nc] = nd;
                pq.push({nd, v, nc});
            }
        }
    }

    int ans = INF;
    for (int c = 0; c <= V; c++) ans = min(ans, dist[Y][c]);
    if (ans == INF) ans = -1;
    printf("%d\n", ans);
    return 0;
}
